<?php require_once 'config.php'; if(!current_user()) {flash('error','Please sign in before checkout.');redirect('login.php');} $items=[];$total=0;try{$ids=array_keys($_SESSION['cart']??[]);if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=db()->prepare("SELECT * FROM products WHERE id IN ($marks)");$stmt->execute($ids);foreach($stmt as $item){$item['quantity']=$_SESSION['cart'][$item['id']];$total+=$item['quantity']*$item['price'];$items[]=$item;}}}catch(Throwable $e){}if(!$items)redirect('shop.php');$tax=$total*.16;$shipping=$total>=5000?0:250;$grand=$total+$tax+$shipping;$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf']??null)){try{$pdo=db();$pdo->beginTransaction();$stmt=$pdo->prepare('INSERT INTO orders(user_id,total,tax,shipping,address,payment_method) VALUES(?,?,?,?,?,?)');$stmt->execute([current_user()['id'],$grand,$tax,$shipping,trim($_POST['address']),$_POST['payment_method']]);$orderId=$pdo->lastInsertId();$line=$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');foreach($items as $item)$line->execute([$orderId,$item['id'],$item['quantity'],$item['price']]);$pdo->commit();log_admin_activity('Customer order placed','order',(int)$orderId,'Order created by user '.current_user()['id']);$_SESSION['cart']=[];flash('success','Order #'.$orderId.' received. We will be in touch shortly.');redirect('account.php');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error='We could not place that order. Please check your details and try again.';}}$pageTitle='Checkout';include 'includes/header.php'; ?>
<section class="section"><div class="container cart-layout"><div class="form-card"><div class="eyebrow">Almost there</div><h1>Checkout.</h1><?php if($error): ?><div class="notice"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="form-group"><label>Delivery address</label><textarea class="form-control" name="address" rows="4" required placeholder="Street, neighbourhood, town"></textarea></div><div class="form-group"><label>Payment method</label><select class="form-control" name="payment_method"><option value="cod">Cash on delivery</option><option value="mpesa">M-Pesa</option><option value="bank">Bank transfer</option></select></div><button class="btn btn-primary">Place order · KSh <?= number_format($grand) ?></button></form></div><aside class="summary"><h3>Your order</h3><?php foreach($items as $item): ?><div class="summary-line"><span><?= e($item['name']) ?> × <?= $item['quantity'] ?></span><span>KSh <?= number_format($item['quantity']*$item['price']) ?></span></div><?php endforeach; ?><div class="summary-line summary-total"><span>Total</span><span>KSh <?= number_format($grand) ?></span></div></aside></div></section><?php include 'includes/footer.php'; ?>
